"""Compare a recompute against results.json: point estimates exact (rel 1e-9), CIs reported separately. Usage: compare.py RESULTS MINE"""
import sys, json
C = json.load(open(sys.argv[1])); M = json.load(open(sys.argv[2]))
rows = []; worst_pt = 0; worst_ci = 0
for k in ("targets", "l_star", "solves"):
    for kk in C[k]: rows.append((f"{k}/{kk}", C[k][kk], M[k][kk], C[k][kk] == M[k][kk]))
for u in C["units"]:
    for kk, cv in C["units"][u].items():
        mv = M["units"][u][kk]
        if isinstance(cv, list):
            for i in (0, 1):
                d = abs(cv[i] - mv[i]); worst_ci = max(worst_ci, d); rows.append((f"units/{u}/{kk}[{i}]", cv[i], mv[i], d))
        else:
            d = abs(cv - mv) / abs(cv); worst_pt = max(worst_pt, d); rows.append((f"units/{u}/{kk}", cv, mv, d))
for k in ("verdict", "verdict_R_n23", "verdict_R_n29"): rows.append((k, C[k], M[k], C[k] == M[k]))
print("numbers:", len(rows), "worst point rel err:", worst_pt, "worst CI abs diff:", worst_ci)
print("nonnumeric all equal:", all(r[3] is True for r in rows if isinstance(r[3], bool)))
json.dump({"rows": rows, "worst_point_rel": worst_pt, "worst_ci_abs": worst_ci}, open(sys.argv[2] + ".cmp.json", "w"), indent=1)

"""Per-arm cost facts (means over the 40 measured solves). Usage: costfacts.py SCRIPTDIR EXPDIR OUT.json"""
import sys, json, collections, statistics
sys.path.insert(0, sys.argv[1]); import vscore as v
E, OUT = sys.argv[2], sys.argv[3]
out = {}
for n in v.NS:
    recs = [json.loads(l) for j in (0, 1) for l in open(f"{E}/sessions/n{n}-j{j}/session/records.jsonl")]
    meas = [r for r in recs if not r["warmup"]]
    out[str(n)] = {}
    for a in sorted({r["arm"] for r in meas}):
        rr = [r for r in meas if r["arm"] == a]; k = len(rr)
        o = {"solves": k, "verified": sum(r["outcome"]["status"] == "verified" for r in rr)}
        if a.startswith("ic-"):
            ph = collections.defaultdict(float)
            for r in rr:
                for p in r["phases"]: ph[p["name"]] += p["adds"] + p["doubles"]
            tot = sum(ph.values())
            o["charged_group_ops_share_by_phase"] = {p: x / tot for p, x in ph.items()}
            g = lambda name, key: sum(next((p.get("native", {}).get(key, 0) for p in r["phases"] if p["name"] == name), 0) for r in rr) / k
            o["mean_trials"] = g("relations", "trials"); o["mean_lookups"] = g("relations", "lookups"); o["mean_relations"] = g("relations", "relations")
            o["pair_table_entries"] = sorted({next(p["native"].get("pair_table_entries") for p in r["phases"] if p["name"] == "oracle_setup") for r in rr})
            o["pair_table_build_adds"] = sorted({next(p["native"].get("pair_table_build_adds") for p in r["phases"] if p["name"] == "oracle_setup") for r in rr})
            o["fb_signed_points"] = sorted({r["factor_base"]["signed_points"] for r in rr}); o["fb_columns"] = sorted({r["factor_base"]["columns"] for r in rr})
            o["max_trials_cap"] = sorted({r["method"]["params"]["max_trials"] for r in rr}); o["max_trials_used"] = max(g2 for g2 in [next(p["native"].get("trials", 0) for p in r["phases"] if p["name"] == "relations") for r in rr])
            o["reusable_share_of_charged"] = (ph.get("factor_base", 0) + ph.get("oracle_setup", 0)) / tot
            o["bitop_reusable_share"] = sum(int(r["work"]["reusable_bitops"]) for r in rr) / sum(int(r["work"]["bitops"]) for r in rr)
        else:
            o["setup_share_of_total_gae"] = sum(p["gae"] for r in rr for p in r["phases"] if p["name"] == "setup") / sum(r["cost"]["total_gae"] for r in rr)
            o["mean_walk_steps"] = sum(r["counters"]["walk_steps"] for r in rr) / k
            o["unpriced_counts_40_solves"] = {u: sum(r["counters"].get(u, 0) for r in rr) for u in ("canonicalisations_uncharged", "partition_hashes_uncharged", "table_inserts_uncharged", "table_queries_uncharged")}
        o["max_rss_kib"] = max(r["time"]["max_rss_kib"] for r in rr)
        o["median_solve_wall_s"] = statistics.median(r["time"]["solve_wall_ns"] for r in rr) / 1e9
        o["native_count_40_solves"] = sum(v.rec_parts(r)[2] for r in rr)
        out[str(n)][a] = o
json.dump(out, open(OUT, "w"), indent=1)
for n, d in out.items():
    for a, o in d.items(): print(n, a, {k: (round(x, 3) if isinstance(x, float) else ({kk: round(vv, 3) for kk, vv in x.items()} if isinstance(x, dict) else x)) for k, x in o.items()})

"""Section 5a counter breakdown per arm and n (40 measured solves), and 3-point rho slopes. Usage: counters.py SCRIPTDIR EXPDIR OUT.json"""
import sys, json, math
sys.path.insert(0, sys.argv[1]); import vscore as v
E, OUT = sys.argv[2], sys.argv[3]
out = {"counters": {}, "rho_log2S_slope_17_19_23": {}}
for n in v.NS:
    recs = [json.loads(l) for j in (0, 1) for l in open(f"{E}/sessions/n{n}-j{j}/session/records.jsonl")]
    meas = [r for r in recs if not r["warmup"]]; out["counters"][str(n)] = {}
    for a in sorted({r["arm"] for r in meas}):
        rr = [r for r in meas if r["arm"] == a]
        if a == "rho-strong":
            c = {u: sum(r["counters"].get(u, 0) for r in rr) for u in ("canonicalisations_uncharged", "partition_hashes_uncharged", "table_inserts_uncharged", "table_queries_uncharged")}
            c["unit_counted"] = "ecbench.gae total (lower_bound true)"
        else:
            g = lambda ph, k: sum(next((p.get("native", {}).get(k, 0) for p in r["phases"] if p["name"] == ph), 0) for r in rr)
            c = {"relations.trials": g("relations", "trials"), "relations.lookups": g("relations", "lookups"), "factor_base.as_solves": g("factor_base", "as_solves"),
                 "factor_base.frobenius_maps": g("factor_base", "frobenius_maps"), "linear_algebra.row_ops": g("linear_algebra", "row_ops"),
                 "solver.ops": sum((r.get("solver") or {}).get("ops", 0) for r in rr), "unpriced": sum(len(r["cost"]["unpriced"]) for r in rr), "unit_counted": "adds + doubles (lower_bound false)"}
        c["sum"] = sum(x for k, x in c.items() if isinstance(x, int) and k != "unpriced")
        c["equals_band_native_sum"] = c["sum"] == sum(v.rec_parts(r)[2] for r in rr)
        out["counters"][str(n)][a] = c
for u in ("band@0", "band@0.1", "band@1", "bitop"):
    ys = []
    for n in (17, 19, 23):
        recs = [json.loads(l) for j in (0, 1) for l in open(f"{E}/sessions/n{n}-j{j}/session/records.jsonl")]
        rr = [r for r in recs if not r["warmup"] and r["arm"] == "rho-strong"]; ys.append(math.log2(sum(v.S(r, u) for r in rr) / len(rr)))
    out["rho_log2S_slope_17_19_23"][u] = v.ols([17, 19, 23], ys)
json.dump(out, open(OUT, "w"), indent=1)
print(json.dumps(out["rho_log2S_slope_17_19_23"]))
for n, d in out["counters"].items():
    for a, c in d.items(): print(n, a, c)

"""Validator's own GF(2^n) Koblitz-curve check (y^2 + xy = x^3 + a x^2 + 1, a = 1). Usage: python3 -I gf2ec.py EXPDIR OUT.json
Finds the field modulus by search (low-weight irreducible f with G on E), computes #E by the Lucas trace, factors it,
checks [r]G = O and [#E]P = O for random points, re-derives every planted scalar from the seed by uniform_scalar_sha256_v1
(1 + u64be(sha256(canonical({"domain","parts":[model,r,seed,index]})))[:8] mod (r-1)), checks Q on E and [k]G = Q, and for
every record recovered == planted and [recovered]G == Q."""
import sys, json, hashlib, random
E, OUT = sys.argv[1], sys.argv[2]
def pmulmod(a, b, f, n):
    r = 0
    while b:
        if b & 1: r ^= a
        b >>= 1; a <<= 1
        if a >> n & 1: a ^= f
    return r
def ppow(a, e, f, n):
    r = 1
    while e:
        if e & 1: r = pmulmod(r, a, f, n)
        a = pmulmod(a, a, f, n); e >>= 1
    return r
def pmod(a, f):
    df = f.bit_length() - 1
    while a and a.bit_length() - 1 >= df: a ^= f << (a.bit_length() - 1 - df)
    return a
def pgcd(a, b):
    while b: a, b = b, pmod(a, b)
    return a
def irreducible_prime_degree(f, n):  # n prime: irreducible iff x^(2^n) = x mod f and gcd(x^2 + x, f) = 1
    x = 2; t = x
    for _ in range(n): t = pmulmod(t, t, f, n)
    return t == x and pgcd(f, 0b110) == 1
def inv(a, f, n): return ppow(a, (1 << n) - 2, f, n)
class Curve:
    def __init__(s, n, f, a=1): s.n, s.f, s.a = n, f, a
    def m(s, x, y): return pmulmod(x, y, s.f, s.n)
    def on(s, P):
        if P is None: return True
        x, y = P; return s.m(y, y) ^ s.m(x, y) == s.m(s.m(x, x), x) ^ (s.m(x, x) if s.a else 0) ^ 1
    def neg(s, P): return None if P is None else (P[0], P[0] ^ P[1])
    def add(s, P, Q):
        if P is None: return Q
        if Q is None: return P
        x1, y1 = P; x2, y2 = Q
        if x1 == x2:
            if y2 == x1 ^ y1: return None
            if x1 == 0: return None
            l = x1 ^ s.m(y1, inv(x1, s.f, s.n)); x3 = s.m(l, l) ^ l ^ s.a
            return (x3, s.m(x1, x1) ^ s.m(l, x3) ^ x3)
        l = s.m(y1 ^ y2, inv(x1 ^ x2, s.f, s.n)); x3 = s.m(l, l) ^ l ^ x1 ^ x2 ^ s.a
        return (x3, s.m(l, x1 ^ x3) ^ x3 ^ y1)
    def mul(s, k, P):
        R = None
        for b in bin(k)[2:]:
            R = s.add(R, R)
            if b == "1": R = s.add(R, P)
        return R
    def half_trace(s, c):
        h = c; t = c
        for _ in range((s.n - 1) // 2):
            t = s.m(s.m(t, t), s.m(t, t)) if False else s.m(s.m(t, t), 1); t = s.m(t, t); h ^= t
        return h
    def lift(s, x):  # y = x z, z^2 + z = x + a + 1/x^2
        if x == 0: return None
        c = x ^ s.a ^ inv(s.m(x, x), s.f, s.n); z = s.half_trace(c)
        if s.m(z, z) ^ z != c: return None
        return (x, s.m(x, z))
def lucas_trace(n, a=1):
    mu = 1 if a == 1 else -1; v0, v1 = 2, mu
    for _ in range(n - 1): v0, v1 = v1, mu * v1 - 2 * v0
    return v1
def factor(N):
    fs = []; d = 2
    while d * d <= N:
        while N % d == 0: fs.append(d); N //= d
        d += 1
    if N > 1: fs.append(N)
    return fs
def is_prime(N): return N > 1 and factor(N) == [N]
def canon(v): return json.dumps(v, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
def planted(model, r, seed, idx):
    d = hashlib.sha256(canon({"domain": "uniform_scalar_sha256_v1", "parts": [model, r, seed, idx]}).encode()).digest()
    return 1 + int.from_bytes(d[:8], "big") % (r - 1)
out = {}; rng = random.Random(12345); all_ok = True
for n in (17, 19, 23, 29):
    recs = [json.loads(l) for j in (0, 1) for l in open(f"{E}/sessions/n{n}-j{j}/session/records.jsonl")]
    cv = recs[0]["workload"]["curve"]; G = tuple(int(c, 16) for c in cv["generator"]); r = cv["r"]
    cands = []
    for k in range(1, n):
        cands.append((1 << n) | (1 << k) | 1)
    for k1 in range(1, n):
        for k2 in range(1, k1):
            for k3 in range(1, k2): cands.append((1 << n) | (1 << k1) | (1 << k2) | (1 << k3) | 1)
    mods = [f for f in cands if irreducible_prime_degree(f, n) and Curve(n, f).on(G)]
    C = Curve(n, mods[0])
    t = lucas_trace(n); order = (1 << n) + 1 - t; fs = factor(order)
    o = {"n": n, "slug": cv["slug"], "ec1": cv["ec1"], "moduli_with_G_on_E": [hex(f) for f in mods], "modulus": hex(mods[0]),
         "trace_lucas": t, "trace_in_slug": int(cv["slug"].split("-tm")[1].split("-")[0]) == -t if "-tm" in cv["slug"] else None,
         "order": order, "order_matches_record": order == cv["group_order"], "order_factorisation": fs,
         "r": r, "r_prime": is_prime(r), "r_is_largest_prime_factor": r == max(fs), "cofactor": order // r, "cofactor_matches_record": order // r == cv["cofactor"],
         "G": list(cv["generator"]), "G_on_curve": C.on(G), "rG_is_O": C.mul(r, G) is None, "G_not_O": G is not None}
    pts = 0; ok_pts = 0
    while pts < 5:
        P = C.lift(rng.randrange(1, 1 << n))
        if P is None or not C.on(P): continue
        pts += 1; ok_pts += C.mul(order, P) is None
    o["random_points_order_check"] = f"{ok_pts}/5 random points P on E have [#E]P = O"
    model = int(cv["icv1"].rsplit(":", 1)[1], 16)
    tg = {}
    for rec in recs:
        w = rec["workload"]; key = w["workload_id"]
        if key not in tg:
            Q = tuple(int(c, 16) for c in w["target"]); k = w["planted"]
            tg[key] = {"job_seed": w["target_seed"], "target_index": w["target_index"], "workload_id": key, "target": w["target"], "planted": k,
                       "planted_rederived_from_seed": planted(model, r, w["target_seed"], w["target_index"]),
                       "Q_on_curve": C.on(Q), "kG_eq_Q": C.mul(k, G) == Q, "records": 0, "recovered_eq_planted": 0, "recovered_G_eq_Q": 0, "verified": 0, "_Q": Q}
        T = tg[key]; T["records"] += 1
        rv = int(rec["outcome"]["recovered"]); T["recovered_eq_planted"] += rv == T["planted"]
        T["recovered_G_eq_Q"] += C.mul(rv, G) == T["_Q"]; T["verified"] += rec["outcome"]["status"] == "verified"
    for T in tg.values():
        T.pop("_Q"); T["planted_matches_law"] = T["planted_rederived_from_seed"] == T["planted"]
        T["ok"] = T["planted_matches_law"] and T["Q_on_curve"] and T["kG_eq_Q"] and T["records"] == T["recovered_eq_planted"] == T["recovered_G_eq_Q"] == T["verified"]
    o["targets"] = list(tg.values()); o["records_checked"] = len(recs); o["distinct_targets"] = len(tg)
    o["all_targets_ok"] = all(T["ok"] for T in tg.values()) and len(tg) == 8
    o["curve_ok"] = all(o[k] for k in ("order_matches_record", "r_prime", "cofactor_matches_record", "G_on_curve", "rG_is_O")) and ok_pts == 5
    all_ok &= o["all_targets_ok"] and o["curve_ok"]
    out[str(n)] = o
    print(n, o["modulus"], len(mods), "t", t, "order", order, fs, "r", r, "h", order // r, o["curve_ok"], o["random_points_order_check"], "targets ok", sum(T["ok"] for T in tg.values()), "records", len(recs))
out["all_ok"] = all_ok
json.dump(out, open(OUT, "w"), indent=1); print("all_ok", all_ok)

"""Robustness analyses for fb-pt-lgrow-k1. Usage: robust.py SCRIPTDIR EXPDIR RIDGE_SESSIONS_GLOB OUT.json"""
import sys, json, math, random, glob, collections
sys.path.insert(0, sys.argv[1]); import vscore as v
E, RG, OUT = sys.argv[2], sys.argv[3], sys.argv[4]
T = v.load(E); B = 10000; BAND = ("band@0", "band@0.1", "band@1")
def q(xs, p): xs = sorted(xs); return xs[int(len(xs) * p)]
def ci(xs): return [q(xs, .025), q(xs, .975)]
def draws(seed):
    rng = random.Random(seed); return [{n: [rng.randrange(8) for _ in range(8)] for n in v.NS} for _ in range(B)]
D0 = draws(0)
def boot(fn, u, dr=D0):
    return [fn({n: [T[n][i] for i in d[n]] for n in v.NS}, u) for d in dr]
res = {}
# 1. leave-one-target-out
loto = {}
for u in v.UNITS:
    Ds = []; R23 = []; R29 = []
    for n in v.NS:
        for i in range(8):
            Tm = {m: (T[m][:i] + T[m][i + 1:] if m == n else T[m]) for m in v.NS}
            st = v.stats(Tm, u); Ds.append((n, T[n][i]["wid"], st["D"]))
            if n == 23: R23.append(st["R"][23])
            if n == 29: R29.append(st["R"][29])
    loto[u] = {"D_min": min(x[2] for x in Ds), "D_max": max(x[2] for x in Ds), "D_min_case": min(Ds, key=lambda x: x[2])[:2],
               "R_n23_range": [min(R23), max(R23)], "R_n29_range": [min(R29), max(R29)], "all_D_positive": all(x[2] > 0 for x in Ds)}
res["leave_one_target_out"] = loto
# per-target R
res["per_target_R"] = {u: {str(n): [{"wid": t["wid"], "job": t["job"], "R": math.log2(sum(t["S"]["ic-pt-l7"][u]) / sum(t["S"][v.lstar(n)][u]))} for t in T[n]] for n in (23, 29)} for u in v.UNITS}
# 2. leave-one-n-out
def D_sub(Tb, u, ns):
    st = v.stats(Tb, u, ns); return st["D"]
lono = {}
for u in v.UNITS:
    lono[u] = {}
    for drop in v.NS:
        ns = tuple(n for n in v.NS if n != drop)
        pt = D_sub(T, u, ns); bs = boot(lambda Tb, uu: D_sub(Tb, uu, ns), u)
        lono[u][f"drop_{drop}"] = {"ns": list(ns), "D": pt, "ci": ci(bs)}
res["leave_one_n_out"] = lono
# 3. alternative slope estimators: endpoint and segment slopes of D (D_ab = (R_b - R_a)/(b - a), R_17 = R_19 = 0)
def R_all(Tb, u): st = v.stats(Tb, u); return {n: st["R"][n] for n in v.NS}
seg = {}
pairs = [(17, 29), (19, 29), (17, 23), (19, 23), (23, 29)]
for u in v.UNITS:
    pt = R_all(T, u); bs = boot(R_all, u); seg[u] = {}
    for a, b in pairs:
        f = lambda R: (R[b] - R[a]) / (b - a)
        xs = [f(R) for R in bs]
        seg[u][f"{a}->{b}"] = {"D": f(pt), "ci": ci(xs), "P_le_0": sum(x <= 0 for x in xs) / B}
    seg[u]["theil_sen"] = None
res["segment_slopes_of_D"] = seg
def statistics_median(xs):
    xs = sorted(xs); m = len(xs) // 2; return xs[m] if len(xs) % 2 else (xs[m - 1] + xs[m]) / 2
for u in v.UNITS:
    pt = R_all(T, u); bs = boot(R_all, u)
    f = lambda R: statistics_median([(R[b] - R[a]) / (b - a) for i, a in enumerate(v.NS) for b in v.NS[i + 1:]])
    res["segment_slopes_of_D"][u]["theil_sen"] = {"D": f(pt), "ci": ci([f(R) for R in bs])}
# 4. D decomposition: D = sum_n w_n (g7_n - gs_n) = (1*R23 + 7*R29)/84
dec = {}
for u in v.UNITS:
    st = v.stats(T, u); mx = sum(v.NS) / 4; sxx = sum((n - mx) ** 2 for n in v.NS)
    w = {n: (n - mx) / sxx for n in v.NS}
    c23 = w[23] * st["R"][23]; c29 = w[29] * st["R"][29]
    dec[u] = {"ols_weights": w, "D": st["D"], "contrib_n23": c23, "contrib_n29": c29, "share_n29": c29 / st["D"], "identity_holds": abs(st["D"] - c23 - c29) < 1e-12}
res["D_decomposition"] = dec
# 5. bootstrap stream sensitivity
sens = {}
for seed in (1, 2):
    dr = draws(seed); sens[seed] = {}
    for u in BAND:
        bs = boot(lambda Tb, uu: v.stats(Tb, uu), u, dr)
        sens[seed][u] = {"D_ci": ci([b["D"] for b in bs]), "R_n23_ci": ci([b["R"][23] for b in bs]), "R_n29_ci": ci([b["R"][29] for b in bs])}
res["bootstrap_seed_sensitivity"] = sens
# 6. three-point (17, 19, 23) gap slopes, and log2 r per n
res["three_point_slopes_17_19_23"] = {u: {"slope_l7": v.ols([17, 19, 23], [v.stats(T, u)["g7"][n] for n in (17, 19, 23)]), "slope_lstar": v.ols([17, 19, 23], [v.stats(T, u)["gs"][n] for n in (17, 19, 23)])} for u in v.UNITS}
recs_by_n = {n: [json.loads(l) for j in (0, 1) for l in open(f"{E}/sessions/n{n}-j{j}/session/records.jsonl")] for n in v.NS}
res["log2_r"] = {str(n): math.log2(recs_by_n[n][0]["workload"]["curve"]["r"]) for n in v.NS}
# 7. rho setup amortisation
amort = {}
for u in BAND:
    wgt = v.W[u]; share = {}; lrho = {}; l7 = {}; ls = {}
    for n in v.NS:
        rr = [r for r in recs_by_n[n] if not r["warmup"] and r["arm"] == "rho-strong"]
        setup = sum(p["gae"] for r in rr for p in r["phases"] if p["name"] == "setup")
        tot = sum(v.rec_parts(r)[1] + wgt * v.rec_parts(r)[2] for r in rr)
        share[n] = setup / tot
        lrho[n] = math.log2(sum(v.S(r, u) for r in rr) / len(rr))
        l7[n] = math.log2(sum(v.S(r, u) for r in recs_by_n[n] if not r["warmup"] and r["arm"] == "ic-pt-l7") / 40)
        ls[n] = math.log2(sum(v.S(r, u) for r in recs_by_n[n] if not r["warmup"] and r["arm"] == v.lstar(n)) / 40)
