def walk(o, path, acc):
    if isinstance(o, dict):
        for k, v in o.items():
            kl = k.lower()
            if "seed" in kl and isinstance(v, (int, str)) and not isinstance(v, bool):
                acc["seeds"][str(v)].add(kl)
            if k == "workload_id" and isinstance(v, str): acc["wids"].add(v)
            if k == "workload" and isinstance(v, dict) and "target" in v and "curve" in v:
                c = v["curve"]; acc["targets"].add((c.get("slug"), json.dumps(v.get("target")), v.get("planted")))
            walk(v, path + [k], acc)
    elif isinstance(o, list):
        for v in o: walk(v, path, acc)
def scan(paths):
