"""Validator's own scorer (independent of scripts/score.py). Library + CLI.
S_w per record, section 5a band: counted group work (adds + doubles over the phases for IC; total_gae for rho, whose
total is pure group work) plus w GAE per native operation (IC: every phase 'native' operation counter that the band
charges: trials, lookups, as_solves, frobenius_maps, row_ops, solver ops; rho: every *_uncharged counter), divided by sqrt(r).
bitop: work.bitops / sqrt(r)."""
import json, math, collections
SESS = [f"n{n}-j{j}" for n in (17, 19, 23, 29) for j in (0, 1)]
NS = (17, 19, 23, 29)
LSTAR = {17: 7, 19: 7, 23: 9, 29: 10}
IC_NATIVE = {"factor_base": ("as_solves", "frobenius_maps"), "relations": ("trials", "lookups"), "linear_algebra": ("row_ops",)}
UNITS = ("band@0", "band@0.1", "band@1", "bitop")
W = {"band@0": 0.0, "band@0.1": 0.1, "band@1": 1.0}
def rec_parts(r):
    sr = math.sqrt(r["workload"]["curve"]["r"])
    if r["cost"]["lower_bound"]:          # rho: total_gae is the counted group work; unpriced counters listed
        charged = r["cost"]["total_gae"]
        native = sum(v for k, v in r["counters"].items() if k.endswith("_uncharged"))
        unl = set(r["cost"]["unpriced"]); unc = {k for k in r["counters"] if k.endswith("_uncharged")}
        assert unl <= unc and all(r["counters"][k] == 0 for k in unc - unl)   # a counter omitted from 'unpriced' is zero
    else:
        charged = sum(p["adds"] + p["doubles"] for p in r["phases"])
        native = sum(p.get("native", {}).get(k, 0) for p in r["phases"] for k in IC_NATIVE.get(p["name"], ())) + (r.get("solver") or {}).get("ops", 0)
    return sr, charged, native
def S(r, unit):
    sr, charged, native = rec_parts(r)
    if unit == "bitop": return int(r["work"]["bitops"]) / sr
    return (charged + W[unit] * native) / sr
def load(E):
    """returns {n: [target dicts]}, each target {'job','wid','idx','S': {arm: {unit: [5 values]}}} in job then target_index order"""
    out = collections.defaultdict(list)
    for s in SESS:
        n = int(s[1:3])
        recs = [json.loads(l) for l in open(f"{E}/sessions/{s}/session/records.jsonl")]
        wl = {}
        for r in recs:
            if r["warmup"]: continue
            w = r["workload"]["workload_id"]
            t = wl.setdefault(w, {"job": s, "wid": w, "idx": r["workload"]["target_index"], "S": collections.defaultdict(lambda: collections.defaultdict(list)), "status": collections.Counter()})
            for u in UNITS: t["S"][r["arm"]][u].append(S(r, u))
            t["status"][(r["arm"], r["outcome"]["status"])] += 1
        out[n] += sorted(wl.values(), key=lambda t: t["idx"])
    return out
def gap(targets, a, b, u):
    return math.log2(sum(sum(t["S"][a][u]) for t in targets) / sum(sum(t["S"][b][u]) for t in targets))
def ols(xs, ys):
    mx = sum(xs) / len(xs); my = sum(ys) / len(ys)
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / sum((x - mx) ** 2 for x in xs)
def lstar(n): return f"ic-pt-l{LSTAR[n]}"
def stats(T, u, ns=NS):
    g7 = {n: gap(T[n], "ic-pt-l7", "rho-strong", u) for n in ns}
    gs = {n: gap(T[n], lstar(n), "rho-strong", u) for n in ns}
    s7 = ols(list(ns), [g7[n] for n in ns]); ss = ols(list(ns), [gs[n] for n in ns])
    R = {n: gap(T[n], "ic-pt-l7", lstar(n), u) for n in ns}
    return {"g7": g7, "gs": gs, "s7": s7, "ss": ss, "D": s7 - ss, "R": R}
